import{_ as t,c as o,o as a,ag as i}from"./chunks/framework.DZ_cNctr.js";const r="/docs/screenshots/dicom-slide.webp",u=JSON.parse('{"title":"DICOM WSI Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens DICOM WSI slides in your browser, from a folder, a zip or a link. Free, nothing to install or convert.","frontmatter":{"title":"DICOM WSI Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens DICOM WSI slides in your browser, from a folder, a zip or a link. Free, nothing to install or convert."},"headers":[],"relativePath":"guides/dicom-wsi.md","filePath":"guides/dicom-wsi.md"}'),s={name:"guides/dicom-wsi.md"};function n(l,e,d,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="dicom-wsi-slides-in-the-browser" tabindex="-1">DICOM WSI Slides in the Browser <a class="header-anchor" href="#dicom-wsi-slides-in-the-browser" aria-label="Permalink to &quot;DICOM WSI Slides in the Browser&quot;">​</a></h1><p>Open DICOM whole-slide images, as they are. Nothing to convert, nothing to upload. A large slide starts showing right away, because the viewer reads only the part you look at.</p><p>A DICOM slide is a folder of <code>.dcm</code> files. Keep them together.</p><p><img src="'+r+'" alt="A DICOM whole-slide image open in the viewer, with its label and macro pictures"></p><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>A folder of <code>.dcm</code> files on your disk</strong>, in Chrome and Edge. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>One zip made without compression</strong>, in any browser, from your disk or its address. See <a href="./local-files.html#zip-without-compression">Zip Without Compression</a>.</li><li><strong>An address</strong> of the zip: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>The slide.</strong> Zoom from the whole slide down to single cells. Areas the scanner skipped show as white.</li><li><strong>Compression.</strong> JPEG, JPEG 2000 and uncompressed.</li><li><strong>Colour profile.</strong> A slide that carries its scanner&#39;s colour profile is drawn with it. ICC in the RGB settings turns it off. See <a href="./channels.html#icc-colour-profile">Channels</a>.</li><li><strong>Label and overview.</strong> They appear under the title. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Patient details.</strong> The viewer reads only what it needs to draw the slide. Patient names and IDs are never read.</li><li><strong>Pixel size and magnification.</strong> Both come from the slide. When its finest level was resampled, the magnification is left out. Enter it in <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>A zip made with compression</td><td>The files in this zip are compressed, so they cannot be read in parts. Unzip it and open the folder, or make the zip again without compression (zip -0 -r slide.zip folder).</td></tr><tr><td>Another compression</td><td>This DICOM slide uses a compression the viewer cannot read yet.</td></tr><tr><td>Not 8-bit RGB</td><td>This DICOM slide is not 8-bit RGB. The viewer cannot read it yet.</td></tr><tr><td>More than one optical path</td><td>This DICOM slide has more than one optical path. The viewer cannot read it yet.</td></tr><tr><td>No slide in the folder</td><td>No DICOM slide found here.</td></tr><tr><td>A damaged or incomplete slide</td><td>This DICOM slide looks damaged or incomplete.</td></tr></tbody></table><p>Some DICOM slides open only from your computer, not by address. The viewer tells you when.</p><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON or OME-XML, and export both, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> shares test slides in its <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/DICOM/" target="_blank" rel="noreferrer">DICOM folder</a>. Download a slide, then drop it on the viewer. They are CC0. Unpack the zip, or <a href="./local-files.html#zip-without-compression">make it again without compression</a>.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><p>A DICOM file with no frame table and more than 256 frames opens from disk only. By address it would take one request per frame.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses the DICOM slide <code>Hamamatsu-2</code> from the OpenSlide test data, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. Opening one counts as one opened image of the kind &quot;DICOM WSI slide&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',26)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
